from pathlib import Path

import numpy as np


class NumpyEmbeddingLoader:
    """Load user and item embeddings generated by the Two-Tower model."""

    def __init__(self, model_dir):
        self.model_dir = Path(model_dir)

        self.user_embeddings = None
        self.user_ids = None
        self.item_embeddings = None
        self.item_ids = None

    def load(self):
        """Load all embedding arrays and validate their dimensions."""

        required_files = [
            "user_embeddings.npy",
            "user_ids.npy",
            "item_embeddings.npy",
            "item_ids.npy",
        ]

        missing_files = [
            filename
            for filename in required_files
            if not (self.model_dir / filename).exists()
        ]

        if missing_files:
            raise FileNotFoundError(
                "Missing embedding files: "
                + ", ".join(missing_files)
            )

        self.user_embeddings = np.load(
            self.model_dir / "user_embeddings.npy"
        )

        self.user_ids = np.load(
            self.model_dir / "user_ids.npy",
            allow_pickle=True
        )

        self.item_embeddings = np.load(
            self.model_dir / "item_embeddings.npy"
        )

        self.item_ids = np.load(
            self.model_dir / "item_ids.npy",
            allow_pickle=True
        )

        self._validate()

        return self

    def _validate(self):
        """Validate IDs and embedding matrix dimensions."""

        if len(self.user_ids) != len(self.user_embeddings):
            raise ValueError(
                "Number of user IDs does not match "
                "number of user embeddings"
            )

        if len(self.item_ids) != len(self.item_embeddings):
            raise ValueError(
                "Number of item IDs does not match "
                "number of item embeddings"
            )

        if self.user_embeddings.ndim != 2:
            raise ValueError(
                "User embeddings must be a 2D array"
            )

        if self.item_embeddings.ndim != 2:
            raise ValueError(
                "Item embeddings must be a 2D array"
            )

        if self.user_embeddings.shape[1] != self.item_embeddings.shape[1]:
            raise ValueError(
                "User and item embedding dimensions must match"
            )

    def get_user_embedding(self, customer_id):
        """Return the embedding for a customer ID."""

        matches = np.where(
            self.user_ids == str(customer_id)
        )[0]

        if len(matches) == 0:
            return None

        return self.user_embeddings[matches[0]]

    def get_item_embedding(self, article_id):
        """Return the embedding for an article ID."""

        matches = np.where(
            self.item_ids == str(article_id)
        )[0]

        if len(matches) == 0:
            return None

        return self.item_embeddings[matches[0]]
